package com.vandorlabs.persistence;

public final class PanelGlassSettingsTest {
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    public static void main(String[] ignored){
        MemoryPrimitiveData tag=new MemoryPrimitiveData();PanelGlassSettings missing=PanelGlassSettings.read(tag,value->value>=-1?value:-1);require(missing.shade==2&&missing.tint==1&&missing.material==-1&&missing.layout==-1&&!missing.stretch&&missing.textureJoin&&missing.framed&&missing.textureLayout()==1,"current panel defaults differ from standalone glass");int cases=0;
        for(boolean typed:new boolean[]{false,true})for(int value:new int[]{Integer.MIN_VALUE,-2,-1,0,1,2,3,4,18,19,Integer.MAX_VALUE})for(boolean stretch:new boolean[]{false,true}){
            tag=new MemoryPrimitiveData();if(typed){tag.putInt(PanelGlassSettings.SHADE,value);tag.putInt(PanelGlassSettings.TINT,value);tag.putInt(PanelGlassSettings.MATERIAL,value);tag.putInt(PanelGlassSettings.LAYOUT,value);}else{tag.putString(PanelGlassSettings.SHADE,Integer.toString(value));tag.putLong(PanelGlassSettings.TINT,value);tag.putString(PanelGlassSettings.MATERIAL,Integer.toString(value));tag.putLong(PanelGlassSettings.LAYOUT,value);}tag.putBoolean(PanelGlassSettings.STRETCH,stretch);tag.putString(PanelGlassSettings.TEXTURE_JOIN,"true");tag.putString(PanelGlassSettings.FRAMED,"true");PanelGlassSettings data=PanelGlassSettings.read(tag,saved->saved>=-1?saved:-1);
            require(data.shade==(typed?(value>=0&&value<19?value:0):2)&&data.tint==(typed&&value>=0&&value<4?value:1),"strict typed shade/tint defaults and invalid-int clamps");require(data.material==(typed&&value>=-1?value:-1)&&!data.textureJoin&&!data.framed,"strict material and any-tag presence booleans");int raw=typed&&value>=0&&value<3?value:-1;require(data.layout==raw&&data.textureLayout()==(raw<0?(stretch?0:1):raw),"raw layout/stretch pairing");MemoryPrimitiveData output=new MemoryPrimitiveData();data.write(output);require(output.getInt(PanelGlassSettings.LAYOUT)==data.textureLayout()&&output.getBoolean(PanelGlassSettings.STRETCH)==stretch,"writer emits effective layout without normalizing saved stretch");cases++;
        }
        MemoryPrimitiveData output=new MemoryPrimitiveData();PanelGlassSettings.write(output,2,1,-1,true,true,true,1);require(output.getInt(PanelGlassSettings.LAYOUT)==1&&output.getBoolean(PanelGlassSettings.STRETCH),"inconsistent explicit layout and stretch remain distinct");require(PanelGlassSettings.fresh().shade==2,"factory shade2");System.out.println("PanelGlassSettings PASS cases="+cases+" distinct panel schema typed defaults raw fallback and scalar write");
    }
}
